 by={x['id']:x for x in m};seedstatus=collections.Counter(str(x['auditor_http_status']) for x in rows);native=json.loads((r.ROOT/'native-validation.json').read_text());state=json.loads((r.ROOT/'state-extraction-validation.json').read_text())
